classDiagram
    class AmbientComputingDevice {
        +String controlMethod
        +processDataRequest()
    }
    class MemoryController {
        +String dataReadMethod
        +cacheDataRequest()
    }
    class Cache {
        +String cachedData
    }
    AmbientComputingDevice --> MemoryController : "데이터 요청을 처리"
    MemoryController --> Cache : "데이터 요청을 캐시"
